# Custom REST Service in Dynamics AX

Here's a comprehensive guide to create a custom REST service in Dynamics AX/D365FO:

## 1. Create a Data Contract Class

```csharp
[DataContractAttribute]
public class CustomerInfoContract
{
    AccountNum accountNum;
    Name custName;
    CustGroup custGroup;

    [DataMemberAttribute]
    public AccountNum parmAccountNum(AccountNum _accountNum = accountNum)
    {
        accountNum = _accountNum;
        return accountNum;
    }

    [DataMemberAttribute]
    public Name parmCustName(Name _custName = custName)
    {
        custName = _custName;
        return custName;
    }

    [DataMemberAttribute]
    public CustGroup parmCustGroup(CustGroup _custGroup = custGroup)
    {
        custGroup = _custGroup;
        return custGroup;
    }
}
```

## 2. Create Response Contract Class

```csharp
[DataContractAttribute]
public class ResponseContract
{
    str responseMessage;
    boolean isSuccess;

    [DataMemberAttribute]
    public str parmResponseMessage(str _responseMessage = responseMessage)
    {
        responseMessage = _responseMessage;
        return responseMessage;
    }

    [DataMemberAttribute]
    public boolean parmIsSuccess(boolean _isSuccess = isSuccess)
    {
        isSuccess = _isSuccess;
        return isSuccess;
    }
}
```

## 3. Create Service Class

```csharp
[ServiceGroupAttribute('CustomRESTService'),
 ServiceAttribute(
     WebApiUri: 'api/services/CustomerService',
     WebApiMethodName: 'getCustomers',
     WebApiRequestType: WebApiRequestAction::Read),
 ServiceAttribute(
     WebApiUri: 'api/services/CustomerService',
     WebApiMethodName: 'createCustomer',
     WebApiRequestType: WebApiRequestAction::Create)
]
public class CustomerRESTService
{
    [WebApiOperationAttribute(WebApiOperationType::Read)]
    public List getCustomers()
    {
        List customerList = new List(Types::Record);
        CustTable custTable;

        while select custTable
            where custTable.AccountNum != ''
        {
            CustomerInfoContract contract = new CustomerInfoContract();
            contract.parmAccountNum(custTable.AccountNum);
            contract.parmCustName(custTable.Name);
            contract.parmCustGroup(custTable.CustGroup);

            customerList.addEnd(contract);
        }

        return customerList;
    }

    [WebApiOperationAttribute(WebApiOperationType::Create)]
    public ResponseContract createCustomer(
        [WebApiBodyParameterAttribute] CustomerInfoContract _customerContract)
    {
        ResponseContract response = new ResponseContract();
        CustTable custTable;

        try
        {
            custTable.initValue();
            custTable.AccountNum = _customerContract.parmAccountNum();
            custTable.Name = _customerContract.parmCustName();
            custTable.CustGroup = _customerContract.parmCustGroup();
            custTable.insert();

            response.parmIsSuccess(true);
            response.parmResponseMessage("Customer created successfully");
        }
        catch(Exception::Error)
        {
            response.parmIsSuccess(false);
            response.parmResponseMessage("Error creating customer");
        }

        return response;
    }

    [WebApiOperationAttribute(WebApiOperationType::Read)]
    public CustomerInfoContract getCustomerById(str _accountNum)
    {
        CustTable custTable;

        select custTable
            where custTable.AccountNum == _accountNum;

        if(custTable.RecId != 0)
        {
            CustomerInfoContract contract = new CustomerInfoContract();
            contract.parmAccountNum(custTable.AccountNum);
            contract.parmCustName(custTable.Name);
            contract.parmCustGroup(custTable.CustGroup);

            return contract;
        }

        return null;
    }
}
```

## 4. Alternative: Using OData Service (D365FO Method)

```csharp
[DataEntityAttribute]
public class CustomerODataEntity extends common
{
    AccountNum accountNum;
    Name custName;
    CustGroup custGroup;

    [DataFieldAttribute]
    public AccountNum parmAccountNum(AccountNum _accountNum = accountNum)
    {
        accountNum = _accountNum;
        return accountNum;
    }

    [DataFieldAttribute]
    public Name parmCustName(Name _custName = custName)
    {
        custName = _custName;
        return custName;
    }

    [DataFieldAttribute]
    public CustGroup parmCustGroup(CustGroup _custGroup = custGroup)
    {
        custGroup = _custGroup;
        return custGroup;
    }
}
```

## 5. Testing the Service

### Using Postman (GET Request):
```
GET https://yourinstance.cloudax.dynamics.com/api/services/CustomerService/getCustomers
Header: Authorization: Bearer [Token]
```

### Using Postman (POST Request):
```
POST https://yourinstance.cloudax.dynamics.com/api/services/CustomerService/createCustomer
Header: Authorization: Bearer [Token]
Content-Type: application/json

{
  "AccountNum": "CUST001",
  "CustName": "John Doe",
  "CustGroup": "10"
}
```

### Using C# Client:
```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;

class Program
{
    static async Task Main()
    {
        using (HttpClient client = new HttpClient())
        {
            client.DefaultRequestHeaders.Add("Authorization", "Bearer YOUR_TOKEN");

            var response = await client.GetAsync(
                "https://yourinstance.cloudax.dynamics.com/api/services/CustomerService/getCustomers");

            var content = await response.Content.ReadAsStringAsync();
            Console.WriteLine(content);
        }
    }
}
```

## Key Points:

- **DataContractAttribute**: Defines the data structure for serialization
- **ServiceAttribute**: Registers the service and its URI
- **WebApiOperationAttribute**: Specifies operation type (Read, Create, Update, Delete)
- **WebApiBodyParameterAttribute**: For POST/PUT request bodies
- Ensure proper security and authentication
- Test in a development environment first

This provides a complete REST service implementation in Dynamics AX!

